"""Serialize authored relationship questions; no other model payload is reused."""
import json
import re
from pathlib import Path

RUN = Path(__file__).resolve().parent
def refs(*numbers):
    return [f'SRC-{n:03d}' for n in numbers]

def build():
    source_rows = [
        ('The Organization Ontology','W3C','https://www.w3.org/TR/vocab-org/','Recommendation; dated URI pin pending','ontology','Selected organizational links and hierarchy clauses; linkedTo does not imply transitivity or legal control.'),
        ('Relationship Record CDF documentation','GLEIF','https://www.gleif.org/content/4_lei-data/1_access-and-use-lei-data/4_level-2-data-relationship-record-rr-cdf-2-1-format/rr-cdf_version_2.1-documentation.html','RR-CDF 2.1','schema','Introduction, release notes and abstract record content; full XSD constraints not verified.'),
        ('Level 2 Data: Who Owns Whom','GLEIF','https://www.gleif.org/en/lei-data/access-and-use-lei-data/level-2-data-who-owns-whom','Public explanation inspected 2026-09-09; release date unspecified','first-party-doc','Direct and ultimate accounting-consolidating parents; not universal beneficial ownership.'),
        ('Beneficial Ownership Data Standard schema reference','Open Ownership','https://standard.openownership.org/en/latest/standard/reference.html','BODS 0.4; mutable latest alias requires pinning','schema','Selected relationship components, source and record lifecycle clauses. Persons are outside this organization-endpoint model.'),
        ('Open Contracting Data Standard release reference','Open Contracting Partnership','https://standard.open-contracting.org/latest/en/schema/reference/','OCDS 1.1.5','schema','Selected parties, organization references and process-qualified roles; not an entire supplier lifecycle.'),
        ('PROV-O: The PROV Ontology','W3C','https://www.w3.org/TR/prov-o/','Recommendation; dated URI pin pending','ontology','Qualified Association describes activity-agent responsibility, not a general partnership predicate.'),
        ('Date and Time on the Internet: Timestamps','IETF','https://www.rfc-editor.org/rfc/rfc3339','RFC 3339 July 2002','standard','Selected sections 5.6-5.8: precise instants with seconds and offset; preserve date-only legal effect separately.'),
    ]
    sources = [dict(id=f'SRC-{i:03d}',title=t,organization=o,url=u,version_or_date=v,source_type=k,primary_source=True,authority_tier=1 if k!='first-party-doc' else 2,accessed_at='2026-09-09T20:26:00Z',relevance=r) for i,(t,o,u,v,k,r) in enumerate(source_rows,1)]
    record_ids=['relation-identity','participant-roles','recognition-basis','control-interest','collaboration-scope','exchange-link','relationship-time','graph-interpretation','assertion-evidence','relationship-stewardship','external-mapping','maintenance-acceptance']
    sr=[refs(1,2,4),refs(1,4,5),refs(1,4,6),refs(2,3,4),refs(1,6),refs(1,5),refs(4,6,7),refs(1,3,4),refs(4,6),refs(4,5,6),refs(1,2,4,5),refs(4,6,7)]
    qk=[['identity','classification','constraint'],['relationship','relationship','composition'],['evidence','authority','requirement'],['classification','measurement','relationship'],['definition','authority','constraint'],['relationship','state','ownership'],['temporal','provenance','lifecycle'],['constraint','provenance','quality'],['evidence','decision','exception'],['ownership','access','privacy'],['interoperability','interoperability','validation'],['authority','validation','process']]
    text=(RUN/'question-design.md').read_text(encoding='utf-8')
    bundles=[]
    n=0
    for group in re.split(r'(?m)^## ',text)[1:]:
        title=re.sub(r'^\d+\s+','',group.split('\n',1)[0])
        layers=[]
        for section in re.split(r'(?m)^### ',group)[1:]:
            title_line,body=section.split('\n',1)
            name=re.sub(r'^\d+\.\d+\s+','',title_line)
            questions_part,answers=body.split('Answer groups:',1)
            questions=[' '.join(q.split()) for q in re.findall(r'(?ms)^\d\. (.*?\?)(?=\s*\n|$)',questions_part)]
            answer_groups=re.findall(r'([a-zA-Z][a-zA-Z0-9]*)\s*\{([^}]+)\}',answers)
            assert len(questions)==len(answer_groups)==3,(name,questions,answer_groups)
            lid=record_ids[n]
            elements=[dict(id=lid+'-'+key.lower(),name=key,description='Proposed structured answer group: '+ ' '.join(fields.split())+'. Preserve attributed unknowns; nested executable schema and profile constraints remain a hold.',value_kind='object',cardinality='1',required=True,source_refs=sr[n]) for key,fields in answer_groups]
            desc='Qualified relationship assertion for '+name.lower()+'. Retain source scope and do not infer legal or commercial authority from its mere existence.'
            finding=dict(id=lid+'-record',name=name+' record',description=desc,source_refs=sr[n],questions=[dict(id=lid+f'-q{i+1:02d}',text=q,kind=qk[n][i],answer_data=[elements[i]['id']]) for i,q in enumerate(questions)],data_elements=elements,artifacts=[dict(id=lid+'-artifact',name=name+' assertion artifact',description='Versioned '+name.lower()+' assertion and authorized evidence references; referenced contracts and organization records retain their masters.',media_or_form=['application/json','application/yaml','text/markdown','external reference'],serial=True,identity_strategy='Issuer-qualified master ID, else Dimension UUID; immutable revision and exact digest separately. Timestamp alone is not identity.',source_refs=sr[n])],inline_only_rationale=None)
            layers.append(dict(id=lid,name=name,description=desc,source_refs=sr[n],findings=[finding]))
            n+=1
        assert len(layers)==2
        bundles.append(dict(id='relation-'+re.sub('[^a-z]+','-',title.lower()).strip('-'),name=title,description='Inter-organizational '+title.lower()+'.',rationale='Keeps relationship-owned assertions separate from endpoint identities and operational masters; a proposed Vercy grouping, not a normative source hierarchy.',source_refs=sorted(set(s for layer in layers for s in layer['source_refs'])),layers=layers))
    assert n==12 and len(bundles)==6
    model=dict(registry_id='vr.wm-org-012',model_id='WM-ORG-012',name='Inter-organizational Relationship',entry_kind='relationship',purpose='Describe attributed, time-qualified organizational relationships without confusing affiliation, supply, consolidation and ownership.',scope_statement='A source-qualified relationship aggregate with explicit participants, kind, direction, scope and evidence. Real-world relation state, publisher record state and observer claims remain separate. Multi-party arrangements require retained membership context.',in_scope=['Relationship identity, endpoint roles and qualified kind','Control-basis references, collaboration and exchange scope','Temporal assertions, graph constraints, disputes and permitted mappings'],out_of_scope=['Organization identity, contract execution and ownership-register mastership','Customer/account and supplier-qualification lifecycles','Inferring legal authority, beneficial ownership or universal transitivity from a generic link'],boundary_notes=[dict(neighbor=a,distinction=b,source_refs=c) for a,b,c in [('WM-ORG-001 Organization','Reference organization identities; a relationship is not either organization.',refs(1,5)),('WM-ORG-014 and WM-ORG-015','Customer/account and supplier/partner qualification remain separate lifecycle masters; relationships provide scoped links.',refs(5)),('Ownership and accounting consolidation','Qualified relation kinds are not universally equivalent; person beneficial owners are out of endpoint scope.',refs(2,3,4)),('Activity and contract','PROV Association qualifies activity-agent provenance, not inter-organizational partnership; contract execution stays delegated.',refs(5,6))]])
    services=dict(
        dimension=dict(owner_package_requirements=['Declare the relationship-data owner and steward.','Identify organization, contract, ownership and commercial masters.','Bind delegation, access, dispute and retention policies before writes.'],namespace_guidance='Use a master-qualified relationship ID distinct from its endpoint tuple, type, direction and revisions; never merge parallel scopes by names.',registry_links=['Organization registry','Relationship registry','Evidence and assertion revision registry','Model and policy registry']),
        canon_and_patch=dict(canonicalization_rules=['Preserve source definition, endpoint roles, scope and valid interval.','No default equivalence of consolidation, equity, votes, affiliation or supply; no default graph closure.'],patch_rules=['Use namespaced extensions pinned to the base digest with pre/post validation.','Append corrections under expected-head check, retaining evidence and counterclaims.'],compatibility_rules=['Kind, direction, arity or control-basis changes require explicit migration and loss report.','Do not coerce date-only effective values into invented precise timestamps.']),
        artifact_rules=dict(identity_priority=['Authoritative relationship master identifier','Governed issuer-qualified URI','Dimension-generated UUID with namespace'],timestamp_rule='RFC 3339 with seconds and explicit offset or Z for precise recording/observation instants; retain date-only effective precision separately.',serial_naming_rule='Relationship artifact-kind prefix, escaped stable identifier and immutable revision; time is optional display metadata.',integrity_rule='Verify exact-byte digests and revision references; hashes prove neither truth nor commercial authority.'),
        policies=['Relationship assertion does not authorize transactions, contract signatures or legal control decisions.','Do not infer missing, withheld or unreported relationships as proven non-existence.','Only kind-specific reviewed graph rules may derive links; retain inputs and time slice.','Conflicting attributed assertions coexist until an authorized resolution.'],
        crud=dict(read=['Read Dimension policy, kind definition, endpoint roles, source scope, time and assurance before using a relationship.'],create=['Create only an authorized attributed assertion; preserve uncertain participant identity and require a distinct relationship ID.'],update=['Append with expected-head and kind-specific graph checks; keep real-world change separate from record correction.'],delete=['Apply retention/legal-hold policy and authorized tombstones; never terminate contracts or delete endpoint organizations as a side effect.']),
        roles=[dict(name=a,responsibilities=[b]) for a,b in [('Dimension owner','Sets federation and delegation boundaries.'),('Relationship steward','Owns kind, endpoint and scope interpretation.'),('Assertion contributor','Adds attributable claims within authorized scope.'),('Reviewer','Assesses conflicting evidence and proposed graph mappings.'),('Custodian','Maintains access-filtered projections and retention.')]],
        access=dict(default_rule='Deny unless the owning Dimension grants purpose-specific access.',scopes=['bundle','layer','finding','artifact'],exceptions=['Explicit recorded, time-limited delegation only; public endpoint names do not make private relationship evidence public.'],audit_requirements=['Record actor, scope, source revision, conflict decision and disclosure without tokens or private source copies.']),
        agents_bootstrap=dict(filename='AGENTS.md',required_fields=['Name','Type','Specification URL','Storage type URL','Interface URL','Processes URL'],read_order=['Dimension identity, delegation and access policy','Pinned relationship model and kind profile','Endpoint/master references, effective time and evidence','Safe append, dispute, mapping, extension and retirement checks']))
    fnrows=[
        ('resolve-relationship','Resolve qualified relationship','Compare identities and scopes without merging parallel relations.',['Master IDs','Endpoint references','Kind and scope'],['Match, candidates or explicit unknown'],['Read permission and kind definition'],['Read-only; identity ambiguity returns candidates, never automatic same-as'],refs(1,2,4)),
        ('inspect-relationship-graph','Inspect qualified graph','Traverse asserted or explicitly derived relationships at a declared time.',['Start organization','Kinds','Time slice','Allowed rule version'],['Evidence-bearing paths and unknown gaps'],['Authorized endpoints and reviewed kind-specific graph rules'],['Read-only; unsupported transitivity or cycles yield warnings/rejection'],refs(1,3,4)),
        ('record-relationship-assertion','Record attributed assertion','Append evidence-backed claim without creating a real-world agreement.',['Claimant and capacity','Relationship kind/scope','Evidence refs','Expected head'],['New immutable local assertion or conflict report'],['Contributor delegation','Resolved master scope','Schema and graph checks'],['Local append only; no signatures, payments or grants; failed checks leave head unchanged'],refs(4,5,6)),
        ('revise-relationship-lifecycle','Append lifecycle revision','Separate effective termination, correction and record retirement.',['Prior revision','Change reason and evidence','Effective/recorded time'],['Successor revision and lineage'],['Write authority','Expected head and retention check'],['Append with compensating revision for mistakes; never erase provenance or terminate a contract'],refs(4,6,7)),
        ('record-relationship-dispute','Register counterclaim','Preserve incompatible positions for authorized review.',['Contested assertion','Counterevidence','Reviewer-policy reference'],['Attributed contested set and review status'],['Permitted evidence access','No automated truth ranking by recency alone'],['Append dispute; no endpoint coercion or automatic adverse decision'],refs(4,6)),
        ('project-relationship','Export permitted projection','Apply versioned vocabulary mapping with declared losses.',['Authorized fields','Target schema/profile','Mapping fixtures'],['Projection and loss report or refusal'],['Disclosure authority','Verified target compatibility'],['Export only scoped data; unsupported arity/meaning produces refusal; publication needs explicit authority'],refs(1,2,4,5)),
    ]
    functions=[dict(id=i,name=n,description=d,inputs=a,outputs=b,preconditions=c,effects=e,source_refs=s) for i,n,d,a,b,c,e,s in fnrows]
    composition=[dict(target=t,relation=r,purpose=p,required=req,source_refs=s) for t,r,p,req,s in [('WM-ORG-001','REFERENCE','Proposed endpoint-identity reference, not a frozen approved ledger edge.',True,refs(1,5)),('WM-ORG-014','REFERENCE','Proposed customer/account lifecycle delegation where relevant.',False,refs(5)),('WM-ORG-015','REFERENCE','Proposed supplier qualification delegation where relevant.',False,refs(5)),('https://www.w3.org/TR/vocab-org/','ALIGN','Candidate generic links; relationship kind semantics require a profile.',False,refs(1)),('https://standard.openownership.org/en/latest/standard/reference.html','ALIGN','Candidate organization-interest subset only, with explicit endpoint and component loss.',False,refs(4))]]
    dims=[('identity','Qualified ID and parallel relationship scope.'),('classification','Versioned kind, exclusions and control basis.'),('direct properties','Direction, roles, arity, scope and qualified interest.'),('recognition','Attributed evidence and misleading shared-name/address signals.'),('capabilities','Six proposed relationship-record operations, not real-world commercial authority.'),('lifecycle','Real-world state versus publisher retirement and corrections.'),('temporal','Effective interval, precision, observation and recording.'),('relationships','Referenced endpoints and commercial masters.'),('provenance','Assertion source and graph derivation are explicit.'),('ownership','Relationship-data steward distinct from endpoint or equity owner.'),('access','Purpose/field restrictions and redaction reasons.'),('retention','Policy-bound tombstones preserve provenance.'),('interoperability','Kind-qualified mappings and loss declarations.')]
    coverage=dict(claim='Bounded source-grounded proposed relationship context contract; not universal legal semantics or executed adapter conformance.',confidence='medium',checklist=[dict(dimension=d,status='covered',notes=n) for d,n in dims]+[dict(dimension='Physical geometry/material',status='not-applicable',notes='Relational object; physical endpoint properties remain delegated.'),dict(dimension='Independent review and executable acceptance',status='gap',notes='External attempts timed out; nested schemas and round-trip fixtures are not implemented.')],known_omissions=['Claude and Grok each timed out on the sole bounded attempt; Codex-only reviewable-draft, no independent corroboration.','Selected clauses only; exact dated source pins, source licenses and complete normative applicability remain to be verified.','Full RR-CDF XSD fields, BODS/OCDS constraints and real round-trip fixtures have not been validated.','No executable nested answer schema, identity resolver, graph rule engine or commercial operation is delivered.','Jurisdiction-specific partnership, control, reporting-exception and disclosure law remain adopter-owned profile work.','Multi-party and cyclic graph fixtures, relation-ledger approval and independent review remain open.'],conflicts=[],regional_assumptions=['Generic relationship is not a universal legal category. Accounting consolidation and beneficial ownership must retain their source definitions and jurisdictions.'],adversarial_checks=['Reject arbitrary linkedTo transitivity.','Reject shared branding as legal control.','Reject publisher record closure as real-world termination.','Reject absence or non-disclosure as a negative fact.','Reject pairwise flattening of multi-party arrangements without loss.','Reject PROV activity association as equivalent to partnership.','Reject scope-free percentages or indirect graph-derived ownership.','Reject local record update as power to bind an organization.'])
    coverage['checklist'].append(dict(dimension='validation',status='gap',notes='Question/answer traceability and profile checks are specified; executable nested schemas and round-trip/graph fixtures are deferred.'))
    return dict(schema_version='1.0.0',model=model,sources=sources,structure=dict(bundles=bundles),functions=functions,composition=composition,service_layers=services,coverage=coverage)

if __name__=='__main__':
    (RUN/'codex.result.json').write_text(json.dumps(build(),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
